use std::collections::HashSet;
use std::fs::{self, File};
use std::path::{Component, Path};
use std::sync::Arc;

use async_trait::async_trait;
use serde_json::{json, Value};
use tokio_util::sync::CancellationToken;

use crate::files::{ExternalFileMetadata, FileSource, FileStore, FileStoreError};
use crate::tools::{Tool, ToolError, ToolExecutionContext, ToolSpec, ToolVisibility};
use crate::types::{ToolCall, ToolResult};

pub const PUBLISH_FILE_TOOL_NAME: &str = "publish_file";

pub trait FilePublicationSink: Send + Sync {
    fn record_file_published(&self, metadata: &ExternalFileMetadata) -> Result<(), String>;
}

pub struct PublishFileTool {
    file_store: FileStore,
    publication_sink: Arc<dyn FilePublicationSink>,
}

impl PublishFileTool {
    pub fn new(file_store: FileStore, publication_sink: Arc<dyn FilePublicationSink>) -> Self {
        Self {
            file_store,
            publication_sink,
        }
    }
}

#[async_trait]
impl Tool for PublishFileTool {
    fn spec(&self) -> ToolSpec {
        ToolSpec::new(
            PUBLISH_FILE_TOOL_NAME,
            "Publish a local file generated by the agent so the caller can download it.",
            json!({
                "type": "object",
                "required": ["path"],
                "properties": {
                    "path": { "type": "string" },
                    "filename": { "type": "string" },
                    "mime_type": { "type": "string" },
                    "description": { "type": "string" }
                },
                "additionalProperties": false
            }),
        )
    }

    fn visibility(&self) -> ToolVisibility {
        ToolVisibility::PublicOutput
    }

    async fn execute(
        &self,
        call: ToolCall,
        context: ToolExecutionContext,
        cancel: CancellationToken,
    ) -> Result<ToolResult, ToolError> {
        if cancel.is_cancelled() {
            return Ok(publish_error(
                call,
                "tool_cancelled",
                "publish_file was cancelled",
                None,
            ));
        }

        let arguments = match PublishFileArguments::parse(&call.arguments) {
            Ok(arguments) => arguments,
            Err(error) => {
                return Ok(publish_error(
                    call,
                    "invalid_publish_file_arguments",
                    error,
                    None,
                ))
            }
        };
        let resolved = match resolve_publish_file(&context.cwd, &arguments.path) {
            Ok(file) => file,
            Err(error) => return Ok(publish_error(call, error.kind, error.message, None)),
        };
        let filename = arguments
            .filename
            .unwrap_or_else(|| sanitize_default_filename(&arguments.path));
        let mime_type = arguments
            .mime_type
            .or_else(|| Some(infer_mime_type(&filename)));

        let record = match self.file_store.store_open_file(
            &filename,
            mime_type.as_deref(),
            resolved.file,
            FileSource::Published,
            arguments.description,
        ) {
            Ok(record) => record,
            Err(error) => return Ok(file_store_error_result(call, error)),
        };
        let metadata = record.external();
        if let Err(message) = self.publication_sink.record_file_published(&metadata) {
            let _ = self.file_store.remove_file(&metadata.file_id);
            return Ok(publish_error(
                call,
                "timeline_publish_failed",
                message,
                None,
            ));
        }
        let details = serde_json::to_value(&metadata).expect("external file metadata serializes");
        Ok(ToolResult::success(call.id, call.name, details.to_string()).with_details(details))
    }
}

struct PublishFileArguments {
    path: String,
    filename: Option<String>,
    mime_type: Option<String>,
    description: Option<String>,
}

impl PublishFileArguments {
    fn parse(value: &Value) -> Result<Self, String> {
        let object = value
            .as_object()
            .ok_or_else(|| "arguments must be an object".to_owned())?;
        let allowed = ["path", "filename", "mime_type", "description"]
            .into_iter()
            .collect::<HashSet<_>>();
        if let Some(key) = object.keys().find(|key| !allowed.contains(key.as_str())) {
            return Err(format!("unexpected argument: {key}"));
        }
        let path = required_string(value, "path")?;
        Ok(Self {
            path,
            filename: optional_string(value, "filename")?,
            mime_type: optional_string(value, "mime_type")?,
            description: optional_string(value, "description")?,
        })
    }
}

struct PublishPathError {
    kind: &'static str,
    message: String,
}

struct ResolvedPublishFile {
    file: File,
}

fn resolve_publish_file(cwd: &str, path: &str) -> Result<ResolvedPublishFile, PublishPathError> {
    let relative = Path::new(path);
    if relative.is_absolute() {
        return Err(path_error(
            "path_outside_cwd",
            "absolute paths are not allowed",
        ));
    }
    if relative
        .components()
        .any(|component| matches!(component, Component::ParentDir))
    {
        return Err(path_error(
            "path_outside_cwd",
            ".. path components are not allowed",
        ));
    }

    let cwd_path = Path::new(cwd);
    let cwd_canonical = fs::canonicalize(cwd_path).map_err(|error| {
        path_error(
            "cwd_unavailable",
            format!("failed to resolve cwd {}: {error}", cwd_path.display()),
        )
    })?;
    if !cwd_canonical.is_dir() {
        return Err(path_error(
            "cwd_unavailable",
            format!("cwd is not a directory: {}", cwd_canonical.display()),
        ));
    }

    let candidate = cwd_canonical.join(relative);
    let link_metadata = fs::symlink_metadata(&candidate).map_err(|error| {
        let kind = if error.kind() == std::io::ErrorKind::NotFound {
            "file_not_found"
        } else {
            "path_unavailable"
        };
        path_error(
            kind,
            format!("failed to inspect {}: {error}", candidate.display()),
        )
    })?;
    let file_type = link_metadata.file_type();
    if file_type.is_symlink() {
        return Err(path_error(
            "not_regular_file",
            format!("{} is a symlink, not a regular file", candidate.display()),
        ));
    }
    if !file_type.is_file() {
        return Err(path_error(
            "not_regular_file",
            format!("{} is not a regular file", candidate.display()),
        ));
    }

    let real_path = fs::canonicalize(&candidate).map_err(|error| {
        path_error(
            "path_unavailable",
            format!("failed to resolve {}: {error}", candidate.display()),
        )
    })?;
    if !real_path.starts_with(&cwd_canonical) {
        return Err(path_error(
            "path_outside_cwd",
            format!("{} resolves outside cwd", candidate.display()),
        ));
    }
    let real_link_metadata = fs::symlink_metadata(&real_path).map_err(|error| {
        path_error(
            "path_unavailable",
            format!("failed to inspect {}: {error}", real_path.display()),
        )
    })?;
    if real_link_metadata.file_type().is_symlink() || !real_link_metadata.file_type().is_file() {
        return Err(path_error(
            "not_regular_file",
            format!("{} is not a regular file", real_path.display()),
        ));
    }
    let file = File::open(&real_path).map_err(|error| {
        path_error(
            "path_unavailable",
            format!("failed to open {}: {error}", real_path.display()),
        )
    })?;
    let opened_metadata = file.metadata().map_err(|error| {
        path_error(
            "path_unavailable",
            format!(
                "failed to inspect open file {}: {error}",
                real_path.display()
            ),
        )
    })?;
    if !opened_metadata.is_file() {
        return Err(path_error(
            "not_regular_file",
            format!("{} is not a regular file", real_path.display()),
        ));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if opened_metadata.dev() != real_link_metadata.dev()
            || opened_metadata.ino() != real_link_metadata.ino()
        {
            return Err(path_error(
                "path_changed",
                format!(
                    "{} changed while preparing publish_file",
                    real_path.display()
                ),
            ));
        }
    }
    Ok(ResolvedPublishFile { file })
}

fn required_string(value: &Value, key: &'static str) -> Result<String, String> {
    optional_string(value, key)?.ok_or_else(|| format!("{key} is required"))
}

fn optional_string(value: &Value, key: &'static str) -> Result<Option<String>, String> {
    let Some(raw) = value.get(key) else {
        return Ok(None);
    };
    if raw.is_null() {
        return Ok(None);
    }
    let Some(text) = raw.as_str() else {
        return Err(format!("{key} must be a string"));
    };
    let text = text.trim();
    Ok((!text.is_empty()).then(|| text.to_owned()))
}

fn sanitize_default_filename(path: &str) -> String {
    let basename = Path::new(path)
        .file_name()
        .map(|value| value.to_string_lossy())
        .unwrap_or_else(|| "file".into());
    let mut sanitized = basename
        .chars()
        .map(|ch| match ch {
            '/' | '\\' if cfg!(windows) => '_',
            '/' | '\\' => '_',
            ch if ch.is_control() => '_',
            ch => ch,
        })
        .collect::<String>();
    sanitized = sanitized.trim().to_owned();
    if sanitized.is_empty() {
        sanitized = "file".to_owned();
    }
    if sanitized.len() > 255 {
        sanitized = truncate_to_byte_len(&sanitized, 255);
    }
    sanitized
}

fn truncate_to_byte_len(value: &str, max_bytes: usize) -> String {
    let mut truncated = String::new();
    for ch in value.chars() {
        if truncated.len() + ch.len_utf8() > max_bytes {
            break;
        }
        truncated.push(ch);
    }
    truncated
}

fn infer_mime_type(filename: &str) -> String {
    let extension = Path::new(filename)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    match extension.as_str() {
        "csv" => "text/csv",
        "txt" | "log" => "text/plain",
        "md" | "markdown" => "text/markdown",
        "json" => "application/json",
        "html" | "htm" => "text/html",
        "xml" => "application/xml",
        "pdf" => "application/pdf",
        "zip" => "application/zip",
        "gz" => "application/gzip",
        "tar" => "application/x-tar",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "webp" => "image/webp",
        "mp4" => "video/mp4",
        _ => "application/octet-stream",
    }
    .to_owned()
}

fn file_store_error_result(call: ToolCall, error: FileStoreError) -> ToolResult {
    publish_error(
        call,
        error.code(),
        error.to_string(),
        Some(json!({"file_store_kind": format!("{:?}", error.kind())})),
    )
}

fn path_error(kind: &'static str, message: impl Into<String>) -> PublishPathError {
    PublishPathError {
        kind,
        message: message.into(),
    }
}

fn publish_error(
    call: ToolCall,
    kind: &'static str,
    message: impl Into<String>,
    extra: Option<Value>,
) -> ToolResult {
    let message = message.into();
    let mut details = json!({
        "kind": kind,
        "message": message,
    });
    if let (Some(details), Some(extra)) = (details.as_object_mut(), extra) {
        if let Some(extra) = extra.as_object() {
            for (key, value) in extra {
                details.insert(key.clone(), value.clone());
            }
        }
    }
    ToolResult::error(call.id, call.name, message, details)
}

trait ToolResultDetailsExt {
    fn with_details(self, details: Value) -> Self;
}

impl ToolResultDetailsExt for ToolResult {
    fn with_details(mut self, details: Value) -> Self {
        self.details = details;
        self
    }
}
